# 에필로그 새 문장 번역 8: 첫 해 사건(2차분 뒤쪽)
TR = {}
def T(en, en_m, ja1, ja2, ja3): return [(en, ja1), (en, ja2), (en_m, ja3)]
def E_(p, d): TR.update({p + '.' + i: v for i, v in d.items()})
E_('b_trip', {
'b0': ("You decided to leave this city with {N} for the first time. One night, somewhere not far.", "{N}と初めて、この街を出てみることにした。一泊、遠くない場所へ。"),
'b1': ("You bought two tickets at the station. It was the first time you had set out with {N} on a road that did not lead to a fight.", "駅で切符を二枚買った。戦いに行くのではない道を{N}と発つのは初めてだった。"),
'b2': ("Halfway through packing, {N} asked whether there truly was such a thing as a trip that needed no arms.", "{N}が旅行鞄を詰める手を止めて尋ねた。武具を持たなくていい旅が本当にあるのかと。"),
'spa.t': ("Go to a mountain hot spring", "山の温泉へ行く"),
'spa.r0': ("{N} did not come out of the hot water for an hour. When they did, they drank two bottles of milk.", "{N}は熱い湯から一時間出てこなかった。出てきてからは牛乳を二本飲んだ。"),
'spa.r1': ("The mountain air was cold. Beyond the inn window there were more stars than in the city. {N} did not close the window.", "山の空気は冷たかった。宿の窓の外には、街より多くの星があった。{N}は窓を閉めなかった。"),
'spa.r2': T("“To fall asleep tired without having fought. A fine thing.”", "{N} fell asleep the moment they were back in the room. Their face was like a child's.", "「戦わずに疲れて眠るというのは、良いものだな」", "「戦わずに疲れて眠るというのは、良いものですね」", "{N}は部屋に戻るなり眠った。子どものような顔だった。"),
'town.t': ("Walk an unfamiliar town", "知らない町を歩く"),
'town.r0': ("You walked without a map. You got lost, and having got lost, walked farther. {N} said that was more fun.", "地図なしで歩いた。道に迷い、迷ったついでにもっと歩いた。{N}はその方が面白いと言った。"),
'town.r1': ("At the market you ate things you could not name. {N} shared the tasty ones and the strange ones fairly.", "市場で名前も知らない物を買って食べた。{N}は美味しい物と妙な物を公平に分けてくれた。"),
'town.r2': T("“Not a campaign but a journey. With a home to return to, the name changes.”", "{N} stopped at every shop. Their face was already picturing where things would go back home.", "「遠征ではなく旅か。帰る家があると名が変わるのだな」", "「遠征ではなく旅なのですね。帰る家があると名前が変わります」", "{N}が店ごとに立ち止まった。帰ってから置く場所を、もう考えている顔だった。"),
})
E_('b_museum', {
'b0': ("You went to a museum. {N} would not move from one glass case. Inside were things from the age they had lived in.", "博物館へ行った。{N}がひとつの硝子の展示棚の前から動かなかった。自分の生きた時代の品がそこにあった。"),
'b0@now': ("You went to a museum. {N} slowed before the old weapons. A few of those they had held in their own hands, they said. They did not explain.", "博物館へ行った。{N}が古い武器の前で歩みを緩めた。あの中のいくつかは手に握ったことがあると言った。説明はしなかった。"),
'b1': ("There was a name {N} knew on an exhibit label. The description ran three lines. {N} read those three lines for a long time.", "展示の説明文に、{N}の知る名前があった。説明は三行だった。{N}はその三行を長く読んでいた。"),
'b1@now': ("A timeline filled one wall of the gallery. {N} looked for a long time at the very end, the box still empty.", "展示室の年表が壁一面を埋めていた。{N}はいちばん端の、まだ空いている欄をしばらく見ていた。"),
'b2': ("{N} put a hand to the glass and took it away. What lay on the other side was their own age.", "{N}が硝子に手を当てて、離した。向こう側にあるのは自分の時代だった。"),
'b2@now': ("{N} looked at their own face reflected in the glass. The person standing among the exhibits was still alive.", "{N}が硝子に映った自分の顔を見た。展示品の間に立っている人は、まだ生きていた。"),
'listen.t': ("Listen to their account", "話を聞く"),
'listen.r0': ("In a low voice {N} told you what the labels left out. A child nearby pricked up their ears.", "説明文にない話を、{N}が低い声で聞かせてくれた。隣にいた子どもが耳を傾けた。"),
'listen.r1': T("“That is not how that thing is used. Well, who would know?”", "{N} mimed gripping the exhibit. The hand shape differed from the label's.", "「あれはそう使う物ではない。まあ、誰に分かる」", "「あれはそう使う物ではありません。まあ、誰に分かるでしょう」", "{N}が展示品を握る仕草をしてみせた。説明文とは違う手の形だった。"),
'listen.r2': ("The visit took three hours. You had the best guide in the world.", "見学には三時間かかった。あなたには世界でいちばん良い解説者がいた。"),
'leave.t': ("Suggest leaving first", "先に出ようと言う"),
'leave.r0': ("Outside it was bright. {N} let out a breath. Thank you, they said. A little longer and they felt they might have gone over to that side.", "外は明るかった。{N}が息を吐いた。ありがとうと言った。もう少しいたら、向こう側へ行ってしまいそうだったと。"),
'leave.r1': ("{N} did not look back. At a stall outside the museum you bought something hot to eat. That belonged to this age.", "{N}は振り返らなかった。博物館の前の屋台で熱い物を買って食べた。それはこちらの時代の物だった。"),
'leave.r2': T("“Let what has passed stay behind the glass. I am on this side.”", "{N} took your sleeve and walked toward the exit.", "「過ぎたものは硝子の中に置いておこう。私はこちら側にいる」", "「過ぎたものは硝子の中に置いておきましょう。私はこちら側にいます」", "{N}があなたの袖をつかんで、出口の方へ歩いた。"),
})
E_('b_fever', {
'b0': ("You had a fever. You could not get up. {N} put a hand to your forehead, and their face hardened.", "熱が出た。起き上がれなかった。{N}が額に手を当ててみて、顔が強張った。"),
'b1': ("It was only aches and chills. Nothing much, yet {N} wore a graver face than in the war.", "ただの体調不良だった。大したことではないのに、{N}は戦争の時より深刻な顔をした。"),
'b2': ("You took to your bed. Before a battle with no enemy, {N} did not know what to do.", "あなたが寝込んだ。敵のいない戦いを前に、{N}は何をすればいいのか分からなかった。"),
'lean.t': ("Lean on them and rest", "寄りかかって休む"),
'lean.r0': ("{N} stayed by you all night. Changing the cloth, straightening the covers. Clumsy, and never once leaving.", "{N}は一晩中そばにいた。濡れ布巾を替え、布団を直し。不器用で、一度も席を外さなかった。"),
'lean.r1': T("“If only it were an enemy I could cut down. There is nothing to do but guard you.”", "{N} sat on the floor by the bed holding your hand. Until morning.", "「斬れる敵であれば良かったのだが。守るしかないな」", "「斬れる相手であれば良かったのですが。守るしかありませんね」", "{N}が寝台の脇の床に座って、あなたの手を握っていた。朝まで。"),
'lean.r1@mage': T("“If only it were something a spell could drive off. There is nothing to do but watch over you.”", "{N} sat on the floor by the bed holding your hand. Until morning.", "「呪文で追い払えるものであれば良かったのだが。見守るしかないな」", "「呪文で追い払えるものであれば良かったのですが。見守るしかありませんね」", "{N}が寝台の脇の床に座って、あなたの手を握っていた。朝まで。"),
'lean.r2': ("The porridge {N} made was bland. It was the best thing in the world.", "{N}の作った粥は味が薄かった。世界でいちばん美味しかった。"),
'lean.r2@cook': ("The porridge {N} made was seasoned exactly for a sick person's mouth. They were someone who knew even that.", "{N}の作った粥は、病人の口にちょうど合う味付けだった。そんなことまで知っている人だった。"),
'fine.t': ("Say you're fine and get up", "大丈夫だと起き上がる"),
'fine.r0': ("You tried to rise and were laid back down. {N}'s hand was firm. This once, they said, they would not obey.", "起きようとして、また寝かされた。{N}の手は断固としていた。今度だけは命令を聞かないと言った。"),
'fine.r1': ("{N} did not believe you were fine. They stood blocking the front door.", "大丈夫だという言葉を{N}は信じなかった。玄関の前に立ちはだかった。"),
'fine.r2': T("“Leave the habit of overdoing it back in that winter.”", "{N} put your shoes up on a high shelf.", "「無理をする癖は、あの冬に置いてこい」", "「無理をなさる癖は、あの冬に置いてきてください」", "{N}があなたの靴を高い棚の上に載せてしまった。"),
})
E_('b_rumor', {
'b0': ("An article said strange accidents kept happening in a distant city. Gas explosions, unexplained faintings. You both knew what that was.", "遠い街で妙な事故が続いているという記事が出た。ガス爆発、原因不明の昏倒。二人ともそれが何なのか分かった。"),
'b1': ("Word trickled out from the Holy Church. In another land a cup was filling again.", "聖堂教会の方から話が流れてきた。別の土地で、また杯が満ちつつあると。"),
'b2': ("{N} folded the newspaper and set it on the table. Somewhere, seven pairs were gathering again.", "{N}が新聞を畳んで食卓に置いた。どこかでまた七組が集まろうとしていた。"),
'stay.t': ("Say it's not our affair", "自分たちのことではないと言う"),
'stay.r0': ("{N} was silent for a long while, then nodded. The newspaper went into the recycling.", "{N}はしばらく黙ってから頷いた。新聞は古紙の束に入った。"),
'stay.r1': T("“True. My war is over. The one who ended it is right here.”", "{N} closed the newspaper and set a teacup on top of it.", "「そうだ。私の戦争は終わった。終わらせた者がここにいる」", "「そうですね。私の戦争は終わりました。終わらせた人がここにいます」", "{N}が新聞を閉じ、その上に茶碗を置いた。"),
'stay.r2': ("That night {N} checked the locks once more. And that was the last time.", "その夜、{N}がもう一度戸締まりを確かめた。そしてそれが最後だった。"),
'pray.t': ("Pray that someone comes through safe", "誰かの無事を祈る"),
'pray.r0': ("There was nothing you could do. Only hope that one of those seven pairs would end the way you did.", "できることはなかった。ただ、その七組のうち誰かが、こちらのように終わることを願った。"),
'pray.r1': ("{N} said that over there, too, there must be at least one pair with a Servant like them and a Master like you.", "{N}が言った。向こうにも、自分のようなサーヴァントとあなたのようなマスターが一組くらいはいるだろうと。"),
'pray.r2': T("“I will not pray for them to win. I will pray for them to survive.”", "{N} opened the window and looked far off for a long time. A salute to no one in particular.", "「勝てとは祈らない。生き残れと祈ろう」", "「勝ってほしいとは祈りません。生き残ってほしいと祈ります」", "{N}が窓を開けて、遠くを長いこと見ていた。誰にともない挨拶をした。"),
})
E_('b_shop', {
'b0': ("The owner of the alley diner recognizes {N}. The customer who always orders the same thing. {N} seemed to like being called a regular.", "路地の食堂の主人が{N}の顔を覚えている。いつも同じ物を頼む客だと。{N}は常連という言葉が気に入った様子だった。"),
'b1': ("{N} now has a regular shop. Their usual comes without ordering, they said, like a boast.", "{N}に行きつけの店ができた。注文しなくてもいつもの物が出てくると、自慢のように言った。"),
'b2': ("The neighborhood baker gives {N} a little extra. Why, {N} said, they do not know themselves.", "近所のパン屋の主人が{N}におまけをくれる。なぜなのかは本人にも分からないと言った。"),
'go.t': ("Go and eat there together", "一緒に食べに行く"),
'go.r0': ("The owner looked at you and asked: is this the person you're always talking about? {N} spilled their water.", "主人があなたを見て言った。この方がいつも話していたあの人かと。{N}が水をこぼした。"),
'go.r1': ("{N} ordered for two without looking at the menu. They even knew what you would like.", "{N}が品書きを見ずに二人分を頼んだ。あなたの好きそうな物まで知っていた。"),
'go.r2': T("“This seat is mine. From today it is yours as well.”", "{N} pulled out the chair across from where they always sit.", "「この席は私の席だ。今日からはお前の席でもある」", "「この席は私の席です。今日からはあなたの席でもあります」", "{N}がいつも座る席の向かいの椅子を引いてくれた。"),
'hear.t': ("Hear what kind of place it is", "どんな店なのか聞く"),
'hear.r0': ("{N} knew the owner's name, the dog's name, and the day the place is closed. They had become one of this neighborhood.", "{N}は主人の名前も、その家の犬の名前も、休みの曜日も全部知っていた。すっかりこの町の人になったのだ。"),
'hear.r1': ("As you listened, you realized {N} had a map of this neighborhood now. A different map from yours.", "話を聞いているうちに、{N}にこの町の地図ができているのが分かった。あなたの地図とは違う地図だった。"),
'hear.r2': T("“To have shops whose names and faces I know. That, I find, is living.”", "{N} took out the shop's stamp card. Nine stamps.", "「名を知り、顔を知る店がある。それが生きるということだった」", "「名前を知り、顔を知るお店があります。それが生きるということでした」", "{N}が店のスタンプカードを出してみせた。判子が九つだった。"),
})
E_('b_frame', {
'b0': ("You realized there was not a single photo of the two of you. That winter there had been no time to keep any.", "二人で撮った写真が一枚もないことに気づいた。あの冬には残す暇がなかった。"),
'b1': ("Passing a photo studio, {N} stopped. They were looking at the family portraits on display.", "写真館の前を通りかかって、{N}が立ち止まった。飾られた家族写真を見ていた。"),
'b2': ("A photo was needed for the papers. Before the camera {N} was stiffer than before an enemy.", "書類に貼る写真が必要だった。{N}はカメラの前で、敵の前よりも固くなった。"),
'take.t': ("Have one taken at the studio", "写真館で撮る"),
'take.r0': ("The photographer said closer. Closer, closer. {N}'s shoulder touched yours. That was the moment taken.", "写真師がもっと寄ってと言った。もっと、もっと。{N}の肩があなたの肩に触れた。その瞬間が撮られた。"),
'take.r1': T("“So this face will remain. It will be funny to look at when I am old.”", "{N} took the print and looked longer at your face than at their own.", "「この顔が残るのか。年を取ってから見たら笑えるな」", "「この顔が残るのですね。年を取ってから見たら可笑しいでしょう」", "{N}は焼き上がった写真を受け取って、自分の顔よりあなたの顔を長く見ていた。"),
'take.r2': ("The photo went up in the entryway. Where it would be seen with every coming and going.", "写真は玄関に掛けられた。出入りするたびに目に入る場所だった。"),
'snap.t': ("Ask a passerby", "通りがかりの人に頼む"),
'snap.r0': ("A little out of focus, both of you with eyes half closed. That made it the better photo.", "少し焦点が外れ、二人とも目を半分閉じていた。だからこそ良い写真になった。"),
'snap.r1': ("The person who took it said you looked good together. {N} turned those words over all the way home.", "撮ってくれた人が言った。お似合いだと。{N}はその言葉を家に着くまで噛みしめていた。"),
'snap.r2': T("“One more. I was not smiling just now.”", "{N} held up one finger. It meant: just one more.", "「もう一枚。今のは私が笑っていなかった」", "「もう一枚です。今のは私が笑っていませんでした」", "{N}が指を一本立てた。もう一枚だけ撮ろうという意味だった。"),
})
E_('b_hero', {
'b0': ("People in the neighborhood were murmuring that a child had gone missing. {N} had their shoes on before you.", "町で子どもがいなくなったと、人々がざわめいていた。{N}があなたより先に靴を履いた。"),
'b1': ("In the street someone snatched a bag and ran. {N}'s body moved before thought.", "道で誰かが鞄をひったくって逃げた。{N}の体が考えるより先に動いた。"),
'b2': ("Smoke rose from the next building. {N} looked at you once. Not eyes asking leave, but eyes letting you know.", "隣の建物から煙が上がった。{N}があなたを一度見た。許しを求める目ではなく、知らせる目だった。"),
'go.t': ("Tell them to go", "行ってこいと言う"),
'go.r0': ("Thirty minutes later {N} came back. Their clothes were a little dirty, no more. It was done. They had left no name, they said.", "三十分後、{N}が戻ってきた。服が少し汚れただけだった。事は済んでいた。名は残さなかったと言った。"),
'go.r1': T("“The war is over, but the habit remains. Not a bad habit.”", "{N} came back and dusted off their hands. Only dust on them; not even out of breath.", "「戦争は終わっても癖は残った。悪くない癖だ」", "「戦争は終わっても癖は残りました。悪くない癖です」", "{N}が戻ってきて手を払ってみせた。埃がついただけで、息も切れていなかった。"),
'go.r2': ("The next day there was talk in the neighborhood. Someone no one knew had helped and vanished. {N} folded laundry as if they had not heard.", "翌日、町に噂が流れた。誰とも知れない人が助けて消えたと。{N}は知らないふりで洗濯物を畳んでいた。"),
'with.t': ("Go together", "一緒に行く"),
'with.r0': ("The two of you ran. The first time since that winter. You were out of breath, and in step.", "二人で走った。あの冬以来、初めてだった。息が切れ、足並みは揃っていた。"),
'with.r1': ("When it was over you leaned against a wall together catching your breath. {N} laughed. Your rhythm still matches, they said.", "事が済んで、二人で壁にもたれて息を整えた。{N}が笑った。呼吸がまだ合うと。"),
'with.r2': T("“With you beside me it is like that winter. Only this time no one died.”", "{N} held out a fist. You touched yours to it.", "「隣にお前がいると、あの冬のようだな。今度は誰も死ななかったが」", "「隣にあなたがいると、あの冬のようですね。今度は誰も死にませんでしたけれど」", "{N}が拳を差し出した。あなたが拳を合わせた。"),
})
E_('b_fade', {
'b0': ("{N} called forth their arms for the first time in a while. They fit the hand just as before. All that had changed was having no use for them.", "{N}が久しぶりに武具を呼び出した。以前とまったく同じように手に馴染んだ。変わったのは、それを使う当てがないことだけだった。"),
'b0@civil': ("{N} gathered mana at their fingertips. It welled up just as before. All that had changed was having no use for it.", "{N}が指先に魔力を集めてみた。以前とまったく同じように満ちてきた。変わったのは、それを使う当てがないことだけだった。"),
'b0@mage': ("{N} gathered mana at their fingertips. It welled up just as before. All that had changed was having no use for it.", "{N}が指先に魔力を集めてみた。以前とまったく同じように満ちてきた。変わったのは、それを使う当てがないことだけだった。"),
'b1': ("The name of the Noble Phantasm was still on the tip of {N}'s tongue. There was simply no cause to call it. That still seemed to sit oddly with {N}.", "宝具の名は、今も{N}の舌先にあった。呼ぶ用がないだけだ。{N}にはそれがまだしっくり来ないらしかった。"),
'b2': ("{N} skipped the stairs and came up over the railing in one bound — and met a neighbor's eyes. In this world, hiding one's strength is work too.", "{N}が階段を使わず、手すりをひと跳びで越えて上がってきて、隣人と目が合った。この世界では、力を隠すのも仕事だった。"),
'ok.t': ("Say “It's yours even unused”", "「使わなくてもあなたのものだ」と言う"),
'ok.r0': T("{N} looked down at their hand for a long time, then raised their head. “True. It does not vanish for going unused.”", "{N} looked down at their hand for a long time, then took your hand with it. A careful hand, the strength held back.", "{N}はしばらく手を見下ろしてから顔を上げた。「そうだな。使わないからといって消えるものではない」", "{N}はしばらく手を見下ろしてから顔を上げた。「そうですね。使わないからといって消えるものではありません」", "{N}はしばらく手を見下ろしてから、その手であなたの手を握った。力を抜いた、慎重な手だった。"),
'ok.r1': ("To live an ordinary life while holding a hero's strength. {N} decided to call that not waste but luxury.", "英雄の力を持ったまま平凡に暮らすこと。{N}はそれを無駄ではなく贅沢と呼ぶことにした。"),
'ok.r2': ("That evening {N} opened the jam jar for you. The most extravagant jar opener in the world.", "その夕方、{N}がジャムの瓶の蓋を開けてくれた。世界でいちばん贅沢な栓抜きだった。"),
'use.t': ("Look for uses for it together", "力の使い道を一緒に探す"),
'use.r0': ("You helped a neighbor move. {N} took pains not to lift the refrigerator alone. Pretending two were carrying it was the harder part, they said.", "隣人の引っ越しを手伝った。{N}は冷蔵庫を一人で持たないよう苦心した。二人で持つふりをする方が大変だったと言った。"),
'use.r1': T("“The strength that brought down castles now moves a wardrobe. Not a bad use.”", "{N} lifted a heavy box with one hand, then quickly took it in both. There were eyes watching.", "「城を崩した力で箪笥を運ぶか。悪くない使い道だ」", "「城を崩した力で箪笥を運ぶのですね。悪くない使い道です」", "{N}が重い箱を片手で持ち上げて、慌てて両手に持ち直した。人の目があった。"),
'use.r1@mage': T("“The craft that raised temples now hangs a shelf. Not a bad use.”", "{N} started to snap their fingers, stopped, and meekly took the box in both hands. There were eyes watching.", "「神殿を築いた腕で棚を吊るか。悪くない使い道だ」", "「神殿を築いた腕で棚を吊るのですね。悪くない使い道です」", "{N}が指を鳴らしかけてやめ、おとなしく箱を両手で持った。人の目があった。"),
'use.r2': ("On a day of heavy snow, the alley had been cleared by dawn. You were the only one who knew who had done it.", "雪のたくさん降った日、路地の雪が明け方のうちにすっかり片づいていた。誰がやったのか知っているのは、あなただけだった。"),
})
E_('b_lease', {
'b0': ("It was time to renew the lease. The form had a box for the number of occupants.", "家の契約を更新する時期になった。書類に住む人数を書く欄があった。"),
'b1': ("{N} bought next year's calendar. With four months still to go. There were things to write in ahead of time, they said.", "{N}が来年の暦を買ってきた。まだ四か月もあるのに。先に書いておくことがあると言った。"),
'b2': ("Talk turned to next year. That winter, the two of you never even spoke of tomorrow.", "来年の話が出た。あの冬には、明日の話もしなかった二人だった。"),
'two.t': ("Write “two people”", "「二人」と書く"),
'two.r0': ("It was a single numeral. {N} looked at that box for a long time. It was the first document, they said, that counted them among the people.", "数字ひとつだった。{N}はその欄を長く見ていた。自分が人数に入った書類は初めてだと言った。"),
'two.r1': T("“Does it mean I may be here next year as well? …I will read it so.”", "{N} put a finger on the numeral, pointed at themselves, and nodded.", "「来年もここにいていいという意味か。……そう読むことにする」", "「来年もここにいていいという意味でしょうか。……そう読むことにします」", "{N}が書類の数字を指で押さえ、自分を指して、頷いた。"),
'two.r2': ("You stamped it. A two-year promise. Longer than the Command Spells.", "判を押した。二年の約束だった。令呪より長かった。"),
'plan.t': ("Ask what they want to do next year", "来年やりたいことを訊く"),
'plan.r0': ("{N}'s list was long. The top was grand, and the bottom was ‘watch the cherry blossoms from beginning to end.’", "{N}の一覧は長かった。いちばん上は大仰で、いちばん下は『桜を最初から最後まで見る』だった。"),
'plan.r1': ("It took {N} a day to answer. They had never thought about what they wanted to do, they said. There had only been what must be done.", "{N}は答えるのに一日かかった。やりたいことを考えたことがなかったと言った。やるべきことしかなかったと。"),
'plan.r2': T("“Next year. I never thought I would come to use those words.”", "{N} wrote something on the first page of the new calendar. They did not show you.", "「来年、か。その言葉を自分が使うことになるとは思わなかった」", "「来年、ですか。その言葉を自分が使うことになるとは思いませんでした」", "{N}が新しい暦の最初の頁に何かを書いた。見せてはくれなかった。"),
})
